mapper.select:
SELECT COUNT(DISTINCT CONCAT(dns.user_id, '-', dns.summary_date))
FROM daily_nutrition_summaries dns
JOIN guild_members gm ON gm.user_id = dns.user_id
WHERE gm.guild_id = #{guildId}
  AND gm.left_at IS NULL
  AND dns.summary_date BETWEEN #{weekStartDate} AND #{weekEndDate}

SELECT COUNT(1)
FROM quests
WHERE guild_id = #{guildId}
  AND CAST(created_at AS DATE) BETWEEN #{weekStartDate} AND #{weekEndDate}

SELECT COUNT(1)
FROM quests
WHERE guild_id = #{guildId}
  AND status IN ('COMPLETED', 'REWARDED')
  AND CAST(COALESCE(completed_at, updated_at) AS DATE) BETWEEN #{weekStartDate} AND #{weekEndDate}

SELECT COUNT(1)
FROM quests
WHERE battle_id = #{battleId}

SELECT COUNT(1)
FROM boss_battle_conditions
WHERE battle_id = #{battleId}
